void cRSubRing::AI()
{
    cRSubGame* rate = rate_source;
    if (rate->subgame_pause_gate != 0)
        return;

    star_shower_counter++;
    if (star_shower_counter == 3)
        star_shower_counter = 0;

    SubRingState current_state = state;
    if ((unsigned int)current_state > SUB_RING_STATE_EXPANDING)
        return;

    switch (current_state) {
    case SUB_RING_STATE_INACTIVE:
        return;

    case SUB_RING_STATE_ACTIVE:
        if (oscillate_x != 0) {
            float phase = active_phase + active_phase_step;
            active_phase = phase;
            if (phase > 6.28318548f) {
                active_phase = phase - 6.28318548f;
            } else if (phase < 0.0f) {
                active_phase = phase + 6.28318548f;
            }
            transform.position.x = Sin(active_phase) * 3.0f;
        }

        {
        cRSubRingStar* particle = particles;
        int count = SUB_RING_PARTICLE_COUNT;
        do {
            particle->AI();
            particle++;
            count--;
        } while (count != 0);
        }

        if (transform.position.z < owner_player->active_window_min_z) {
            state = SUB_RING_STATE_INACTIVE;
            g_game->active_bod_list.remove_bod(this);

            cRSubRingStar* particle =
                particles;
            int count = SUB_RING_PARTICLE_COUNT;
            do {
                particle->sprite->Kill();
                particle++;
                count--;
            } while (count != 0);
            return;
        } else {
            int current_lives = owner_player->lives;
            if (current_lives < owner_lives_snapshot)
                state = SUB_RING_STATE_EXPAND_PENDING;
            return;
        }

    case SUB_RING_STATE_COLLECT_PENDING:
        state = SUB_RING_STATE_COLLECTING;
        transition_progress = 0.0f;
        transition_step = rate->subgame_rate * 0.0694444478f;
        // fall through

    case SUB_RING_STATE_COLLECTING:
        {
        cRSubRingStar* particle = particles;
        int count = SUB_RING_PARTICLE_COUNT;
        do {
            particle->AI();
            particle++;
            count--;
        } while (count != 0);
        }

        transition_progress += transition_step;
        if (transition_progress > 1.0f) {
            state = SUB_RING_STATE_INACTIVE;
            g_game->active_bod_list.remove_bod(this);

            cRSubRingStar* particle =
                particles;
            int count = SUB_RING_PARTICLE_COUNT;
            do {
                particle->sprite->Kill();
                particle++;
                count--;
            } while (count != 0);
            return;
        } else {
            int count = 0;
            Vector3* target_source =
                &owner_player->cached_camera_target_world;
            Vector3 target_position;
            target_position.x = target_source->x;
            target_position.y = target_source->y;
            target_position.z = target_source->z + 0.200000003f;
            Vector3* current_position = &transform.position;
            Vector3 delta;
            delta.x = target_position.x - current_position->x;
            delta.y = target_position.y - current_position->y;
            delta.z = target_position.z - current_position->z;
            Vector3 scaled_delta;
            scaled_delta.x = delta.x * 0.939999998f;
            scaled_delta.y = delta.y * 0.939999998f;
            scaled_delta.z = delta.z * 0.939999998f;
            current_position->x += scaled_delta.x;
            current_position->y += scaled_delta.y;
            current_position->z += scaled_delta.z;

            do {
                particles[count].radius *= 0.939999998f;
                particles[count].base_position = *current_position;
                count++;
            } while (count < SUB_RING_PARTICLE_COUNT);
            return;
        }

    case SUB_RING_STATE_EXPAND_PENDING:
        state = SUB_RING_STATE_EXPANDING;
        transition_progress = 0.0f;
        transition_step = rate->subgame_rate * 0.0694444478f;
        // fall through

    case SUB_RING_STATE_EXPANDING:
        {
        cRSubRingStar* particle = particles;
        int count = SUB_RING_PARTICLE_COUNT;
        do {
            particle->AI();
            particle++;
            count--;
        } while (count != 0);
        }

        transition_progress += transition_step;
        if (transition_progress > 1.0f) {
            state = SUB_RING_STATE_INACTIVE;
            g_game->active_bod_list.remove_bod(this);

            cRSubRingStar* particle =
                particles;
            int count = SUB_RING_PARTICLE_COUNT;
            do {
                particle->sprite->Kill();
                particle++;
                count--;
            } while (count != 0);
            return;
        } else {
            int count = 0;
            do {
                particles[count].radius *= 1.10000002f;
                particles[count].base_position = transform.position;
                count++;
            } while (count < SUB_RING_PARTICLE_COUNT);
            return;
        }

    default:
        break;
    }

    return;
}

// update_garbage_hazard @ 0x43f200 (thiscall, ret)
// cRSubGarbage::AI(): hover/contact registration, nuke/contact burst setup,
// burst integration, smoke cadence, teardown, and final sprite roll update.

#include "garbage_hazard_slot.h"
#include "player.h"
#include "rmath_random.h"
#include "subgame_runtime.h"


void cRSubGarbage::AI()
{
    cRSubGame* pause_game = owner_game;
    if (!pause_game->subgame_pause_gate) {
        int current_state = state;
        switch ((unsigned int)current_state) {
        case SUB_GARBAGE_STATE_INACTIVE:
            goto function_return;

        case SUB_GARBAGE_STATE_ACTIVE: {
            Vector3* position = &transform.position;
            Vector3* visual_position = &sprite->position;
            *visual_position = *position;

            cRSubGoldy* owner = owner_player;
            if (transform.position.z < owner->active_window_min_z)
            {
                Kill();
                return;
            }

            if (owner->nuke_effect_progress > 0.0f) {
                float x = position->x;
                state = SUB_GARBAGE_STATE_BURST_PENDING;
                if (x > 0.0f)
                    collision_side = SUB_GARBAGE_COLLISION_SIDE_RIGHT;
                else
                    collision_side = SUB_GARBAGE_COLLISION_SIDE_LEFT;
                owner->ScoreAdd(SUBGOLDY_SCORE_GARBAGE, 0);
            }

            owner_game->enemy_manager.Register(
                transform.position,
                radius,
                0,
                this);
            break;
        }

        case SUB_GARBAGE_STATE_BURST_PENDING: {
            state = SUB_GARBAGE_STATE_BURST;
            Vector3 random_velocity;
            random_velocity.x = (float)SRAND(0.1f, "GDI");
            random_velocity.y = (float)RAND(0.2f, 0) + 0.1f;
            random_velocity.z = (float)RAND(0.30000001f, 0);
            cRSubGame* rate_game = owner_game;
            Vector3* burst_velocity = &velocity;
            float rate = rate_game->subgame_rate;
            Vector3 staged_velocity;

            staged_velocity.x = rate * random_velocity.x;
            double wide_rate = rate;
            staged_velocity.y = float(random_velocity.y * wide_rate);
            staged_velocity.z = float(random_velocity.z * wide_rate);
            *burst_velocity = staged_velocity;

            int side = collision_side;
            double adjusted_x;
            if (side == SUB_GARBAGE_COLLISION_SIDE_RIGHT) {
                adjusted_x = burst_velocity->x < 0.0f
                    ? -(double)burst_velocity->x
                    : (double)burst_velocity->x;
            } else if (side == SUB_GARBAGE_COLLISION_SIDE_LEFT) {
                adjusted_x = -(burst_velocity->x < 0.0f
                    ? -burst_velocity->x
                    : burst_velocity->x);
            } else {
                goto side_adjustment_complete;
            }
            burst_velocity->x = (float)adjusted_x;
